    public static class Vsop87
    {
        /// <summary>Evaluate a VSOP87B series -> (L, B, R) in radians/AU for TT Julian date.</summary>
        public static void Evaluate(double[][][] body, double jdTt, out double lon, out double lat, out double radius)
        {
            double t = (jdTt - AstroTime.J2000) / 365250.0; // Julian millennia
            double[] r = new double[3];
            for (int v = 0; v < 3; v++)
            {
                double sum = 0, tp = 1;
                for (int p = 0; p < 6; p++)
                {
                    double[] terms = body[v][p];
                    double s = 0;
                    for (int i = 0; i < terms.Length; i += 3)
                        s += terms[i] * Math.Cos(terms[i + 1] + terms[i + 2] * t);
                    sum += s * tp;
                    tp *= t;
                }
                r[v] = sum;
            }
            lon = AstroTime.NormalizeRadians(r[0]);
            lat = r[1];
            radius = r[2];
        }

        /// <summary>Heliocentric rectangular position in the J2000 ecliptic frame (AU).</summary>
        public static Vec3d HeliocentricEclipticJ2000(double[][][] body, double jdTt)
        {
            Evaluate(body, jdTt, out double l, out double b, out double r);
            // VSOP87B is referred to the dynamical ecliptic/equinox J2000; the tiny frame bias to ICRS (~0.02") is ignored.
            return Vec3d.FromSpherical(l, b) * r;
        }
    }

