        public static void Compute(double jdTt, out double lonRad, out double latRad, out double distanceKm)
        {
            double T = AstroTime.CenturiesSinceJ2000(jdTt);
            double d2r = AstroTime.Deg2Rad;
            // Mean elements (degrees), Meeus 47.1–47.7
            double Lp = AstroTime.NormalizeDegrees(218.3164477 + 481267.88123421 * T - 0.0015786 * T * T + T * T * T / 538841.0 - T * T * T * T / 65194000.0);
            double D  = AstroTime.NormalizeDegrees(297.8501921 + 445267.1114034 * T - 0.0018819 * T * T + T * T * T / 545868.0 - T * T * T * T / 113065000.0);
            double M  = AstroTime.NormalizeDegrees(357.5291092 + 35999.0502909 * T - 0.0001536 * T * T + T * T * T / 24490000.0);
            double Mp = AstroTime.NormalizeDegrees(134.9633964 + 477198.8675055 * T + 0.0087414 * T * T + T * T * T / 69699.0 - T * T * T * T / 14712000.0);
            double F  = AstroTime.NormalizeDegrees(93.2720950 + 483202.0175233 * T - 0.0036539 * T * T - T * T * T / 3526000.0 + T * T * T * T / 863310000.0);
            double A1 = AstroTime.NormalizeDegrees(119.75 + 131.849 * T);
            double A2 = AstroTime.NormalizeDegrees(53.09 + 479264.290 * T);
            double A3 = AstroTime.NormalizeDegrees(313.45 + 481266.484 * T);
            double E = 1.0 - 0.002516 * T - 0.0000074 * T * T;
            double E2 = E * E;

            double sl = 0, sr = 0, sb = 0;
            for (int i = 0; i < LR.Length; i++)
            {
                Term t = LR[i];
                double arg = (t.D * D + t.M * M + t.Mp * Mp + t.F * F) * d2r;
                double e = t.M == 0 ? 1.0 : (Math.Abs(t.M) == 1 ? E : E2);
                sl += t.A * e * Math.Sin(arg);
                sr += t.B * e * Math.Cos(arg);
            }
            for (int i = 0; i < Bt.Length; i++)
            {
                Term t = Bt[i];
                double arg = (t.D * D + t.M * M + t.Mp * Mp + t.F * F) * d2r;
                double e = t.M == 0 ? 1.0 : (Math.Abs(t.M) == 1 ? E : E2);
                sb += t.A * e * Math.Sin(arg);
            }
            // Additive terms (Venus, Jupiter, flattening of Earth)
            sl += 3958 * Math.Sin(A1 * d2r) + 1962 * Math.Sin((Lp - F) * d2r) + 318 * Math.Sin(A2 * d2r);
            sb += -2235 * Math.Sin(Lp * d2r) + 382 * Math.Sin(A3 * d2r) + 175 * Math.Sin((A1 - F) * d2r) + 175 * Math.Sin((A1 + F) * d2r)
                  + 127 * Math.Sin((Lp - Mp) * d2r) - 115 * Math.Sin((Lp + Mp) * d2r);

            lonRad = AstroTime.NormalizeDegrees(Lp + sl / 1e6) * d2r;
            latRad = (sb / 1e6) * d2r;
            distanceKm = 385000.56 + sr / 1000.0;
        }
    }
